  "validity": false,
  "label": "0 Invalid rules",
  "reason": "This rule describes a normal HVAC control logic: when outdoor air temperature is high, the cooling water loop setpoint reduces to prevent overcooling or energy waste. This is standard operational behavior, not an anomaly."
}

{
  "validity": false,
  "label": "0 Invalid rules",
  "reason": "This rule lacks context and represents a plausible operational state rather than an anomaly. High outside temperature often requires lower cooling setpoints to maintain comfort, so this association does not inherently indicate a design or performance issue."
}

{
  "validity": false,
  "label": "0 Invalid rules",
  "reason": "The rule describes normal HVAC operation: when outdoor air temperature is high, the cooling water loop setpoint lowers to maximize efficiency and prevent overheating. This is a standard control strategy, not an anomaly."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High fan speed combined with low outdoor wet-bulb temperature typically cools the coil efficiently. A high supply air temperature indicates insufficient cooling performance under these favorable conditions, suggesting an operational issue like dirty coils or flow restriction."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High fan speed combined with low outdoor wet-bulb temperature should not cause high supply air temperature. This indicates a control failure or mechanical fault in the cooling system."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "High fan speed combined with low outdoor wet-bulb temperature typically indicates improper control logic or a malfunctioning sensor causing unnecessary energy consumption and potential system inefficiency."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "Low security load combined with high pump speed yet low discharge pressure suggests a potential control logic error or mechanical malfunction during operation, rather than expected performance behavior."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "Low secondary load with high primary speed suggests a mismatch where the system attempts to compensate excessively without matching demand, indicating an operational issue rather than design or performance degradation."
}

{
  "validity": true,
  "label": "2 Operational anomaly",
  "reason": "Low secondary load combined with high primary fan speed typically causes excessive pressure drop at low flow, indicating an operational mismatch or control fault rather than a design flaw."
}
